-- 142 foundation grantee edges, salvaged from foundations.notable_grants.
--
-- The community money finder can show which foundations hold money (step 3) but not who any of
-- them funded. The database has 96 foundation grantee edges in `foundation_grantees`, only 8
-- carrying an amount, which is not enough to tell a community organisation anything. (The 61 rows
-- under dataset `foundations` are `subsidiary_of`, not grants.)
--
-- foundations.notable_grants is the only grant-shaped text already held: 793 foundations, 2,606
-- entries, scraped free text with no direction and no structure. Two passes made it usable, and
-- the split of labour is the point:
--
--   code   amounts, years, and a candidate organisation matched by capitalised NAME SPAN against
--          the ACNC register. Jev is never asked to read a figure: it cannot count, do maths or
--          order dates. Matching whole sentences instead of spans halved the yield, because
--          "Grant to Shepparton Foodshare for food relief staples" scores poorly against
--          "Shepparton Foodshare" with the sentence still attached.
--   Jev    direction, and refusing look-alikes. It found 1,296 entries to be grants the foundation
--          made, 589 its own activities, 438 money to individuals, and 77 with the arrow BACKWARDS
--          (Developing East Arnhem lists Rio Tinto and the NT Government, which funded it). It
--          refused 978 of 1,607 candidates: Utju Health Service is not Wyn Health Service, and
--          Albany Community Library is not Manning Community Toy Library.
--
-- What lands here is only what passed both gates at 0.9 or better: 142 edges, 96 foundations, 105
-- grantees, 65 with an amount. `confidence` is `inferred`, which is the honest label - the source
-- is scraped text adjudicated by a model, not a filing.
--
-- THIS IS A FLOOR, NOT A PICTURE. 1,296 real grants are named in that text and only 142 resolve to
-- an organisation on the register. Do not sum these amounts and call it a foundation's giving.
-- Real coverage needs foundation annual reports, which is a separate piece of work that starts
-- with a terms-of-use review.
--
-- Scripts: scripts/extract-notable-grants.mjs, then scripts/jev-adjudicate-grants.mjs.
-- Apply: scripts/db-apply.sh supabase/migrations/20260923093000_foundation_notable_grants.sql

BEGIN;

CREATE TEMP TABLE nb (funder_abn text, grantee_abn text, amount numeric, yr integer,
                      source_record_id text, props jsonb) ON COMMIT DROP;

;

-- Idempotent: this dataset is rebuilt wholesale whenever the two scripts are re-run.
DELETE FROM gs_relationships WHERE dataset = 'foundation_notable_grants';

   dataset, source_record_id, confidence, first_seen, last_seen, properties)
SELECT s.id, t.id, 'grant', nb.amount, CASE WHEN nb.amount IS NULL THEN NULL ELSE 'AUD' END, nb.yr,
       'foundation_notable_grants', nb.source_record_id, 'inferred', now(), now(), nb.props
  FROM nb
  JOIN gs_entities s ON s.abn = nb.funder_abn
  JOIN gs_entities t ON t.abn = nb.grantee_abn
 WHERE s.id <> t.id;   -- the no-self-loop constraint covers this dataset's siblings; belt and braces

COMMIT;
